/* Root + responsive frame */
.bfusion-root.kpg-root {
    width: 100%;
    height: 100%;
    overflow: hidden;
    font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
    background: var(--bf-bg, #FFFFFF);
    position: relative;
    color: var(--bf-strong, #1F2A44);
    padding-bottom: 24px;
    --kpg-header-band: #8b1a2e;
    --kpg-header-text: #ffffff;
    --kpg-accent: #1d4ed8;
    --kpg-plan: #cbd5e1;
    --kpg-ok: #16a34a;
    --kpg-warn: #d97706;
    --kpg-risk: #dc2626;
    --kpg-header-fs: 12.5px;
    --kpg-body-fs: 13px;
    --kpg-title-fs: 15px;
    --kpg-subtitle-fs: 11px;
    --kpg-search-fs: 13px;
    --kpg-button-fs: 11.5px;
    --kpg-insight-fs: 12px;
    --kpg-insight-h-fs: 13px;
    --kpg-dialog-fs: 13.5px;
    --kpg-gridlines-color: var(--bf-grid, #eef0f4);
    --kpg-insight-accent: #E8612A;
    --kpg-grand-total-bg: #f3f4f6;
    --kpg-subtotal-bg-0: #e0f2fe;
    --kpg-subtotal-bg-1: #fae8ff;
    --kpg-subtotal-bg-2: #d1fae5;
}
.bfusion-root.kpg-root *,
.bfusion-root.kpg-root *::before,
.bfusion-root.kpg-root *::after { box-sizing: border-box; }

/* Layout chain — flex column from shell down through grid-wrap */
.kpg-shell { position: absolute; inset: 0; overflow: hidden; display: flex; flex-direction: column; }
.kpg-board { flex: 1 1 auto; min-height: 0; overflow: hidden; display: flex; flex-direction: column; width: 100%; height: 100%; }
.kpg-head, .kpg-legendbar, .kpg-strip { flex: 0 0 auto; min-width: 0; }
.kpg-body { flex: 1 1 0; min-width: 0; min-height: 0; overflow: hidden; display: flex; flex-direction: row; align-items: stretch; }
.kpg-main { flex: 1 1 auto; min-width: 0; min-height: 0; display: flex; flex-direction: column; overflow: hidden; }
.kpg-grid-wrap { flex: 1 1 0; min-height: 0; overflow: auto; background: var(--bf-bg, #FFFFFF); }

/* Header chrome */
.kpg-head { background: var(--bf-surface-alt, #F4F5F7); border-bottom: 1px solid var(--bf-rule, #E5E7EB); padding: 10px 14px; }
.kpg-head__titlebar { display: flex; flex-direction: row; align-items: center; gap: 10px; }
.kpg-head__spacer { flex: 1; }
.kpg-head__title { font-size: var(--kpg-title-fs, 15px); font-weight: 600; color: var(--bf-strong, #1F2A44); line-height: 1.2; }
.kpg-head__subtitle { font-size: var(--kpg-subtitle-fs, 11px); color: var(--bf-muted, #667079); margin-top: 1px; }
.kpg-search { display: inline-flex; align-items: center; gap: 6px; background: var(--bf-bg, #FFFFFF); border: 1px solid var(--bf-rule, #E5E7EB); border-radius: 4px; padding: 6px 12px; color: var(--bf-muted, #667079); font-size: var(--kpg-search-fs, 13px) !important; min-width: 220px; }
.kpg-search input { font-family: inherit; font-size: var(--kpg-search-fs, 13px) !important; line-height: 1.4; color: var(--bf-strong, #1F2A44); background: transparent; border: 0; outline: 0; flex: 1; min-width: 0; }
.kpg-search input::placeholder { color: var(--bf-muted, #667079); opacity: 1; font-size: inherit; }
.kpg-search__icon { flex-shrink: 0; }
.kpg-search__clear { border: 0; background: transparent; cursor: pointer; color: var(--bf-muted, #667079); font-size: 16px; padding: 0 4px; }
.kpg-head__iconbtn, .kpg-info-btn {
    width: 28px; height: 28px; border-radius: 4px; border: 1px solid var(--bf-rule, #E5E7EB); background: var(--bf-bg, #FFFFFF);
    color: var(--bf-text, #242424); cursor: pointer; padding: 0; display: inline-flex; align-items: center; justify-content: center;
}
.kpg-head__iconbtn--active { background: rgba(139,26,46,0.08); border-color: var(--kpg-header-band); color: var(--kpg-header-band); }
.kpg-info-btn { width: 24px; height: 24px; border-radius: 50%; }
.kpg-info-btn__i { font-family: Georgia, serif; font-style: italic; font-weight: 700; font-size: 13px; line-height: 1; }

/* Legend bar */
.kpg-legendbar { display: flex; align-items: center; justify-content: space-between; padding: 8px 16px; border-top: 1px solid var(--bf-rule, #E5E7EB); background: var(--bf-bg, #FFFFFF); font-size: var(--kpg-button-fs, 11.5px); color: var(--bf-muted, #667079); }
.kpg-legend { display: inline-flex; align-items: center; gap: 14px; flex-wrap: wrap; }
.kpg-legend__item { display: inline-flex; align-items: center; gap: 6px; }
.kpg-legend__item--tone { background: transparent; border: 1px solid transparent; padding: 3px 8px; border-radius: 999px; cursor: pointer; color: inherit; font: inherit; font-size: var(--kpg-button-fs, 11.5px); transition: all 0.12s ease; }
.kpg-legend__item--tone:hover { border-color: var(--bf-rule, #E5E7EB); background: var(--bf-bg, #FFFFFF); }
.kpg-legend__item--active { border-color: var(--kpg-insight-accent, #E8612A); background: rgba(232, 97, 42, 0.08); color: var(--bf-strong, #1F2A44); font-weight: 600; }
.kpg-legend__clearfilter { background: transparent; border: 0; color: var(--kpg-insight-accent, #E8612A); cursor: pointer; font-size: var(--kpg-button-fs, 11.5px); padding: 0 4px; font-weight: 600; }
.kpg-legend__sep { color: var(--bf-rule, #E5E7EB); margin: 0 4px; }
.kpg-legend__line { display: inline-block; width: 18px; height: 0; border-top: 2px solid var(--kpg-accent); }
.kpg-legend__line--plan { border-top-style: dashed; border-top-color: var(--kpg-plan); }
.kpg-legend__right { display: inline-flex; align-items: center; gap: 10px; flex-wrap: wrap; }
.kpg-legend__copybtn { background: var(--bf-bg, #FFFFFF); border: 1px solid var(--bf-rule, #E5E7EB); border-radius: 4px; padding: 3px 9px; font-size: var(--kpg-button-fs, 11px); color: var(--bf-text, #242424); cursor: pointer; display: inline-flex; align-items: center; gap: 5px; }
.kpg-legend__copybtn--active { background: rgba(232, 97, 42, 0.12); border-color: var(--kpg-insight-accent, #E8612A); color: var(--kpg-insight-accent, #E8612A); font-weight: 600; }
.kpg-legend__copybtn:hover { border-color: var(--bf-rule, #E5E7EB); }

/* Grouped by chip */
.kpg-grouped-by { display: inline-flex; align-items: center; gap: 4px; font-size: 11px; }
.kpg-grouped-by__label { color: var(--bf-text, #242424); font-weight: 600; margin-right: 4px; }
.kpg-grouped-by__chip { display: inline-flex; align-items: center; padding: 1px 3px 1px 8px; border-radius: 999px; background: var(--bf-surface-alt, #F4F5F7); border: 1px solid var(--bf-rule, #E5E7EB); font-weight: 600; line-height: 1.5; }
.kpg-grouped-by__chip--depth-0 { border-left: 3px solid #1d4ed8; padding-left: 6px; }
.kpg-grouped-by__chip--depth-1 { border-left: 3px solid #c026d3; padding-left: 6px; }
.kpg-grouped-by__chip--depth-2 { border-left: 3px solid #0891b2; padding-left: 6px; }
.kpg-grouped-by__x { background: transparent; border: 0; color: var(--bf-muted, #667079); font-size: 14px; cursor: pointer; padding: 2px 5px; border-radius: 50%; }

/* KPI strip */
.kpg-strip { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 10px; padding: 10px 14px; border-bottom: 1px solid var(--bf-rule, #E5E7EB); background: var(--bf-bg, #FFFFFF); }
.kpg-tile { background: var(--bf-bg, #FFFFFF); border: 1px solid var(--bf-rule, #E5E7EB); border-top: 3px solid var(--kpg-accent); border-radius: 8px; padding: 10px 12px; position: relative; }
.kpg-tile__header { display: flex; align-items: center; justify-content: space-between; gap: 6px; margin-bottom: 4px; }
.kpg-tile__label { font-size: max(10px, calc(var(--kpg-kpi-fs, 22px) * 0.48)); color: var(--bf-text, #242424); text-transform: uppercase; letter-spacing: 0.5px; font-weight: 600; flex: 1; min-width: 0; }
.kpg-tile__value { font-size: var(--kpg-kpi-fs, 22px); font-weight: 700; line-height: 1.1; color: var(--kpg-accent); font-variant-numeric: tabular-nums; }
.kpg-tile__sub { font-size: max(10px, calc(var(--kpg-kpi-fs, 22px) * 0.48)); color: var(--bf-muted, #667079); margin-top: 4px; }
.kpg-tile__trend { display: flex; align-items: center; gap: 8px; margin-top: 6px; }
.kpg-tile__delta { font-size: max(10px, calc(var(--kpg-kpi-fs, 22px) * 0.5)); font-weight: 700; }
.kpg-tile--withtrend .kpg-tile__value { font-size: calc(var(--kpg-kpi-fs, 22px) * 0.91); }
.kpg-tile__gear { background: transparent; border: 0; padding: 2px; color: var(--bf-muted, #667079); cursor: pointer; opacity: 0; }
.kpg-tile:hover .kpg-tile__gear { opacity: 1; }

/* Grid + columns */
.kpg-grid { width: 100%; border-collapse: separate; border-spacing: 0; font-size: var(--kpg-body-fs, 13px); color: var(--bf-strong, #1F2A44); }
.kpg-th { text-align: left; background: var(--kpg-header-band); color: var(--kpg-header-text); font-size: var(--kpg-header-fs, 12.5px); font-weight: 600; padding: 12px 14px; position: sticky; top: 0; z-index: 3; white-space: nowrap; }
.kpg-th--right { text-align: right; }
.kpg-th--frozen { position: sticky; left: 0; z-index: 4; background: var(--kpg-header-band); color: var(--kpg-header-text); }
.kpg-th__inner { display: inline-flex; align-items: center; gap: 6px; }
.kpg-th__sortbtn { background: transparent; border: 0; color: inherit; padding: 0; cursor: pointer; display: inline-flex; align-items: center; gap: 5px; font: inherit; }
.kpg-th__gear { background: transparent; border: 0; color: var(--kpg-header-text); opacity: 0.65; padding: 2px 4px; cursor: pointer; display: inline-flex; align-items: center; border-radius: 3px; }
.kpg-th__gear:hover { opacity: 1; background: rgba(0,0,0,0.12); }
.kpg-th__resize { position: absolute; right: 0; top: 0; bottom: 0; width: 6px; cursor: col-resize; }

.kpg-td { padding: 11px 14px; border-bottom: 1px solid var(--kpg-gridlines-color, var(--bf-rule, #E5E7EB)); vertical-align: middle; background: var(--bf-bg, #FFFFFF); white-space: nowrap; }
.bfusion-root.kpg-root.kpg-hgrid-off .kpg-td { border-bottom: 0; }
.bfusion-root.kpg-root.kpg-vgrid-on .kpg-td { border-right: 1px solid var(--kpg-gridlines-color, var(--bf-rule, #E5E7EB)); }
.bfusion-root.kpg-root.kpg-vgrid-on .kpg-td:last-child { border-right: 0; }
.bfusion-root.kpg-root.kpg-vgrid-on .kpg-th { border-right: 1px solid rgba(255,255,255,0.18); }
/* Indent for nested-row identity cell — the lowest level (depth = group count) gets the most padding */
.kpg-td--right { text-align: right; font-variant-numeric: tabular-nums; }
.kpg-td--frozen { position: sticky; left: 0; z-index: 1; background: var(--bf-bg, #FFFFFF); }
.kpg-grid--striped tbody .kpg-row:nth-of-type(even) .kpg-td { background: var(--bf-bg, #FFFFFF); }
.kpg-row { cursor: pointer; }
.kpg-row:hover .kpg-td { background: var(--bf-surface-alt, #F4F5F7); }
.kpg-row:hover .kpg-td--frozen { background: var(--bf-surface-alt, #F4F5F7); }
.kpg-row--selected .kpg-td, .kpg-row--selected .kpg-td--frozen { background: #dbeafe !important; }

/* Identity / Status dot */
.kpg-id { display: flex; align-items: center; gap: 10px; min-width: 200px; }
.kpg-id__text { display: flex; flex-direction: column; min-width: 0; }
.kpg-id__name { font-weight: 600; color: var(--bf-strong, #1F2A44); line-height: 1.25; }
.kpg-id__meta { font-size: calc(var(--kpg-body-fs, 13px) - 2px); color: var(--bf-muted, #667079); margin-top: 1px; }
.kpg-dot { width: 10px; height: 10px; border-radius: 50%; flex-shrink: 0; display: inline-block; background: var(--bf-muted, #667079); }
.kpg-dot--ok { background: var(--kpg-ok); }
.kpg-dot--warn { background: var(--kpg-warn); }
.kpg-dot--risk { background: var(--kpg-risk); }

/* Pills */
.kpg-pill { display: inline-flex; align-items: center; gap: 6px; padding: 2px 10px 2px 6px; border-radius: 999px; font-size: calc(var(--kpg-body-fs, 13px) - 2px); font-weight: 600; border: 1px solid transparent; }
.kpg-pill__icon { display: inline-flex; align-items: center; justify-content: center; width: calc(var(--kpg-body-fs, 13px) + 1px); height: calc(var(--kpg-body-fs, 13px) + 1px); border-radius: 50%; font-size: calc(var(--kpg-body-fs, 13px) - 4px); font-weight: 700; color: #fff; flex-shrink: 0; }
.kpg-pill--ok { background: var(--bf-bg, #FFFFFF); color: #059669; border-color: #bbf7d0; }
.kpg-pill--ok .kpg-pill__icon { background: #059669; }
.kpg-pill--warn { background: var(--bf-hint-bg, #FFFBEB); color: #d97706; border-color: var(--bf-hint-border, #FDE68A); }
.kpg-pill--warn .kpg-pill__icon { background: #d97706; }
.kpg-pill--risk { background: var(--bf-surface-alt, #F4F5F7); color: #dc2626; border-color: #fecaca; }
.kpg-pill--risk .kpg-pill__icon { background: var(--bf-band, #1F2A44); }
.kpg-pill--neutral { background: var(--bf-surface-alt, #F4F5F7); color: var(--bf-muted, #667079); border-color: var(--bf-rule, #E5E7EB); }
.kpg-pill--neutral .kpg-pill__icon { background: var(--bf-muted, #667079); }

/* Status rollup chips on Grand Total + subtotal rows */
.kpg-rollup-grp { display: inline-flex; gap: 4px; align-items: center; flex-wrap: nowrap; max-width: 100%; overflow: hidden; vertical-align: middle; }
.kpg-rollup { display: inline-flex; align-items: center; gap: 2px; padding: 1px 7px; min-height: calc(var(--kpg-body-fs, 13px) + 4px); border-radius: 999px; font-size: calc(var(--kpg-body-fs, 13px) - 2px); font-weight: 700; line-height: 1.2; white-space: nowrap; flex-shrink: 0; border: 1px solid transparent; }
.kpg-rollup--ok   { background: #d1fae5; color: #047857; border-color: #6ee7b7; }
.kpg-rollup--warn { background: #fef3c7; color: var(--bf-hint-text, #92400E); border-color: #fcd34d; }
.kpg-rollup--risk { background: #fee2e2; color: #b91c1c; border-color: #fca5a5; }

/* Chrome scaling — buttons + icons + sort/gear track --kpg-body-fs/--kpg-header-fs */
.kpg-head__iconbtn { width: calc(var(--kpg-header-fs, 12.5px) * 2.2); height: calc(var(--kpg-header-fs, 12.5px) * 2.2); }
.kpg-head__iconbtn svg { width: calc(var(--kpg-header-fs, 12.5px) * 1.1); height: calc(var(--kpg-header-fs, 12.5px) * 1.1); }
.kpg-info-btn { width: calc(var(--kpg-header-fs, 12.5px) * 1.9); height: calc(var(--kpg-header-fs, 12.5px) * 1.9); }
.kpg-info-btn__i { font-size: calc(var(--kpg-header-fs, 12.5px) * 1.05); }
.kpg-search__icon { width: calc(var(--kpg-header-fs, 12.5px) * 1); height: calc(var(--kpg-header-fs, 12.5px) * 1); }
.kpg-th__sort { font-size: calc(var(--kpg-header-fs, 12.5px) * 0.75); }
.kpg-th__gear svg { width: calc(var(--kpg-header-fs, 12.5px) * 1); height: calc(var(--kpg-header-fs, 12.5px) * 1); }
.kpg-th__filter svg, .kpg-th__filter--active svg { width: calc(var(--kpg-header-fs, 12.5px) * 0.9); height: calc(var(--kpg-header-fs, 12.5px) * 0.9); }
.kpg-legendbar { font-size: calc(var(--kpg-body-fs, 13px) - 1.5px); }
.kpg-legend__copybtn { font-size: calc(var(--kpg-body-fs, 13px) - 2px); }
.kpg-legend__copybtn svg { width: calc(var(--kpg-body-fs, 13px) - 1px); height: calc(var(--kpg-body-fs, 13px) - 1px); }
.kpg-grouped-by { font-size: calc(var(--kpg-body-fs, 13px) - 2px); }
.kpg-btn--mini { font-size: calc(var(--kpg-body-fs, 13px) - 2px); }
.kpg-btn--mini svg { width: calc(var(--kpg-body-fs, 13px) - 1px); height: calc(var(--kpg-body-fs, 13px) - 1px); }

/* RAG */
.kpg-rag { display: inline-flex; align-items: center; gap: 4px; padding: 4px 2px; }
.kpg-rag__dot { width: 10px; height: 10px; border-radius: 50%; background: var(--bf-muted, #667079); flex-shrink: 0; }
.kpg-rag__dot.kpg-dot--ok { background: var(--kpg-ok); }
.kpg-rag__dot.kpg-dot--warn { background: var(--kpg-warn); }
.kpg-rag__dot.kpg-dot--risk { background: var(--kpg-risk); }

/* Variance / Number */
.kpg-num { font-variant-numeric: tabular-nums; }
.kpg-num--zero { color: var(--bf-muted, #667079); opacity: 0.55; }
.kpg-var { font-variant-numeric: tabular-nums; font-weight: 600; display: inline-flex; align-items: center; gap: 4px; }
.kpg-var--pos { color: #16a34a; }
.kpg-var--neg { color: #dc2626; }
.kpg-var--flat { color: var(--bf-muted, #667079); }

/* Progress bar */
.kpg-prog { display: flex; align-items: center; gap: 8px; min-width: 120px; justify-content: flex-end; }
.kpg-prog__bar { flex: 1; height: 8px; background: var(--bf-surface-alt, #F4F5F7); border-radius: 4px; overflow: hidden; min-width: 60px; max-width: 140px; }
.kpg-prog__bar span { display: block; height: 100%; border-radius: 4px; background: var(--kpg-accent); }
.kpg-prog__val { font-size: 11.5px; color: var(--bf-text, #242424); font-variant-numeric: tabular-nums; min-width: 40px; text-align: right; }
.kpg-oor { margin-left: 4px; color: var(--kpg-warn, #b45309); font-size: 0.85em; cursor: help; }

/* Bullet, sparklines */
.kpg-bullet-cell { display: flex; align-items: center; gap: 10px; min-width: 280px; }
.kpg-bullet-val { font-variant-numeric: tabular-nums; min-width: 90px; }
.kpg-bullet { position: relative; display: inline-block; width: 180px; height: 18px; flex-shrink: 0; }
.kpg-bullet__range { position: absolute; inset: 4px 0; background: var(--bf-rule, #E5E7EB); border-radius: 2px; }
.kpg-bullet__actual { position: absolute; top: 6px; left: 0; height: 10px; background: var(--bf-band, #1F2A44); border-radius: 1px; }
.kpg-bullet__actual--over { background: var(--kpg-risk); }
.kpg-bullet__target { position: absolute; top: 2px; bottom: 2px; width: 2px; background: var(--bf-band, #1F2A44); }
.kpg-spark-bar, .kpg-spark-line, .kpg-boxplot { display: inline-block; vertical-align: middle; overflow: hidden; }
.kpg-spark-bar svg, .kpg-spark-line svg, .kpg-boxplot svg { display: block; width: 100%; height: 100%; }
.kpg-spark-line path { fill: none; stroke-linejoin: round; stroke-linecap: round; }
.kpg-spark-line path.kpg-spark-line__actual { stroke-width: 1.7; }
.kpg-spark-line path.kpg-spark-line__plan { stroke-width: 1.5; }

/* Date / null */
.kpg-date { color: var(--bf-text, #242424); font-variant-numeric: tabular-nums; }
.kpg-null { color: var(--bf-muted, #667079); }

/* Group header / Subtotal / Totals */
.kpg-row--group { cursor: pointer; user-select: none; }
.kpg-td--group { background: var(--bf-surface-alt, #F4F5F7); border-top: 1px solid var(--bf-rule, #E5E7EB); border-bottom: 1px solid var(--bf-rule, #E5E7EB); padding: 8px 14px; position: sticky; left: 0; z-index: 1; }
.kpg-td--group-depth-0 { padding-left: 14px; font-weight: 700; }
.kpg-td--group-depth-1 { padding-left: 36px; font-weight: 600; }
.kpg-td--group-depth-2 { padding-left: 58px; font-weight: 500; }
.kpg-group__chev { display: inline-block; width: calc(var(--kpg-body-fs, 13px) * 1.1); margin-right: 6px; font-size: var(--kpg-body-fs, 13px); font-weight: 600; color: var(--bf-text, #242424); }
.kpg-row--group-depth-0 .kpg-group__chev { color: #1d4ed8; }
.kpg-row--group-depth-1 .kpg-group__chev { color: #c026d3; }
.kpg-row--group-depth-2 .kpg-group__chev { color: #0891b2; }
.kpg-group__dot { display: inline-block; width: 8px; height: 8px; border-radius: 50%; margin-right: 8px; }
.kpg-group__label { color: var(--bf-text, #242424); font-weight: 600; }
.kpg-group__key { font-weight: 700; color: var(--bf-strong, #1F2A44); }
.kpg-row--group-ok .kpg-td--group { background: var(--bf-bg, #FFFFFF); border-color: #bbf7d0; }
.kpg-row--group-warn .kpg-td--group { background: var(--bf-hint-bg, #FFFBEB); border-color: var(--bf-hint-border, #FDE68A); }
.kpg-row--group-risk .kpg-td--group { background: var(--bf-surface-alt, #F4F5F7); border-color: #fecaca; }

.kpg-td--subtotal { font-weight: 600; color: var(--bf-strong, #1F2A44); padding: 9px 14px; border-bottom: 1px solid var(--bf-rule, #E5E7EB); }
.kpg-td--subtotal-depth-1 { padding-left: 36px; font-size: 0.95em; }
.kpg-td--subtotal-depth-2 { padding-left: 58px; font-size: 0.92em; font-style: italic; }
.kpg-row--subtotal-depth-0 .kpg-td--subtotal,
.kpg-row--subtotal-depth-0 .kpg-td--subtotal.kpg-td--frozen { background: var(--kpg-subtotal-bg-0, #e0f2fe) !important; }
.kpg-row--subtotal-depth-1 .kpg-td--subtotal,
.kpg-row--subtotal-depth-1 .kpg-td--subtotal.kpg-td--frozen { background: var(--kpg-subtotal-bg-1, var(--bf-surface-alt, #F4F5F7)) !important; }
.kpg-row--subtotal-depth-2 .kpg-td--subtotal,
.kpg-row--subtotal-depth-2 .kpg-td--subtotal.kpg-td--frozen { background: var(--kpg-subtotal-bg-2, #d1fae5) !important; }

.kpg-row--totals .kpg-td, .kpg-row--totals .kpg-td--frozen {
    background: var(--kpg-grand-total-bg, var(--bf-surface-alt, #F4F5F7)) !important;
    font-weight: 700;
    border-top: 2px solid rgba(0,0,0,0.15);
    border-bottom: 2px solid rgba(0,0,0,0.15);
}
.kpg-row--totals-top .kpg-td { position: sticky; top: var(--kpg-head-h, 44px); z-index: 2; border-bottom: 2px solid var(--kpg-header-band); }
.kpg-row--totals-top .kpg-td--frozen { z-index: 3; }
.kpg-totals-label { font-weight: 700; }

/* Insight rail — BFusion branded (orange accent + gradient panel + info button) */
.kpg-rail { flex: 0 0 260px; background: linear-gradient(180deg, var(--bf-bg, #FFFFFF) 0%, var(--bf-surface, #F8F9FB) 100%); border-left: 1px solid var(--bf-rule, #E5E7EB); padding: 12px 14px 14px; display: flex; flex-direction: column; min-height: 0; overflow-y: auto; font-size: var(--kpg-insight-fs, 12px); }
.kpg-rail--collapsed { flex: 0 0 24px; padding: 12px 0 0; cursor: pointer; background: var(--bf-surface, #F8F9FB); border-left: 1px solid var(--bf-rule, #E5E7EB); display: flex; align-items: flex-start; justify-content: center; }
.kpg-rail--collapsed .kpg-rail__arrow { color: var(--kpg-insight-accent, #E8612A); font-size: var(--kpg-insight-fs, 12px); line-height: 1; }
.kpg-rail__head { display: flex; align-items: center; justify-content: space-between; gap: 6px; margin-bottom: 10px; padding-bottom: 8px; border-bottom: 2px solid var(--kpg-insight-accent, #E8612A); }
.kpg-rail__titles { display: flex; flex-direction: column; min-width: 0; flex: 1; }
.kpg-rail__title { font-size: var(--kpg-insight-h-fs, 13px); font-weight: 700; color: var(--bf-text, #242424); letter-spacing: 0.4px; }
.kpg-rail__subtitle { font-size: calc(var(--kpg-insight-fs, 12px) - 2px); color: var(--bf-muted, #667079); text-transform: uppercase; letter-spacing: 0.8px; font-weight: 600; }
.kpg-rail__info { width: 20px; height: 20px; border-radius: 50%; border: 1px solid var(--bf-rule, #E5E7EB); background: var(--bf-bg, #FFFFFF); color: var(--bf-muted, #667079); cursor: pointer; padding: 0; display: inline-flex; align-items: center; justify-content: center; font-family: Georgia, serif; font-style: italic; font-weight: 700; font-size: 11px; transition: all 0.15s ease; }
.kpg-rail__info:hover { background: var(--kpg-insight-accent, #E8612A); color: #ffffff; border-color: var(--kpg-insight-accent, #E8612A); }
.kpg-rail__toggle { width: 22px; height: 22px; border: 0; background: transparent; color: var(--bf-muted, #667079); font-size: calc(var(--kpg-insight-fs, 12px) - 1px); cursor: pointer; border-radius: 4px; }
.kpg-rail__toggle:hover { background: rgba(232, 97, 42, 0.08); color: var(--kpg-insight-accent, #E8612A); }
.kpg-rail__group { display: flex; flex-direction: column; gap: 8px; }
.kpg-rail__divider { margin-top: 12px; padding-top: 8px; border-top: 1px dashed var(--bf-rule, #E5E7EB); font-size: calc(var(--kpg-insight-fs, 12px) - 2px); font-weight: 700; text-transform: uppercase; letter-spacing: 0.6px; color: var(--bf-muted, #667079); margin-bottom: 8px; }
.kpg-rail__divider--accent { color: var(--kpg-insight-accent, #E8612A); border-top-color: var(--kpg-insight-accent, #E8612A); border-top-style: solid; }
.kpg-insight { display: flex; gap: 8px; padding: 9px 11px; background: var(--bf-bg, #FFFFFF); border-radius: 6px; border-left: 3px solid var(--bf-rule, #E5E7EB); box-shadow: 0 1px 2px rgba(15, 23, 42, 0.04); }
.kpg-insight--info { border-left-color: #3b82f6; }
.kpg-insight--success { border-left-color: var(--kpg-ok); }
.kpg-insight--warning { border-left-color: var(--kpg-warn); }
.kpg-insight--critical { border-left-color: var(--kpg-risk); }
.kpg-insight__icon { width: calc(var(--kpg-insight-fs, 12px) + 10px); height: calc(var(--kpg-insight-fs, 12px) + 10px); border-radius: 50%; background: var(--bf-surface, #F8F9FB); display: inline-flex; align-items: center; justify-content: center; font-size: calc(var(--kpg-insight-fs, 12px) - 1px); font-weight: 700; flex-shrink: 0; color: var(--bf-text, #242424); }
.kpg-insight__body { min-width: 0; flex: 1; }
.kpg-insight__label { font-size: calc(var(--kpg-insight-fs, 12px) - 1px); font-weight: 700; color: var(--bf-text, #242424); text-transform: uppercase; letter-spacing: 0.4px; }
.kpg-insight__text { font-size: var(--kpg-insight-fs, 12px); color: var(--bf-text, #242424); line-height: 1.4; margin-top: 2px; }

/* Info popover */
.kpg-info-pop { position: absolute; inset: 0; display: none; z-index: 30; background: rgba(15,23,42,0.18); align-items: center; justify-content: center; padding: 24px; }
.kpg-info-pop[data-state="shown"] { display: flex; }
.kpg-info-pop__inner { background: var(--bf-bg, #FFFFFF); border-radius: 10px; max-width: 420px; width: 100%; padding: 18px 22px 20px; box-shadow: 0 12px 32px rgba(15,23,42,0.20); position: relative; max-height: 86%; overflow-y: auto; }
.kpg-info-pop__close { position: absolute; top: 8px; right: 10px; border: 0; background: transparent; font-size: 18px; cursor: pointer; color: var(--bf-muted, #667079); line-height: 1; }
.kpg-info-pop__title { font-size: 14px; font-weight: 700; color: var(--bf-strong, #1F2A44); padding-bottom: 6px; border-bottom: 2px solid #E8612A; margin-bottom: 10px; }
.kpg-info-pop__desc { font-size: 12px; color: var(--bf-text, #242424); line-height: 1.5; margin-bottom: 12px; }
.kpg-info-pop__subhead { font-size: 11px; font-weight: 700; color: var(--bf-muted, #667079); text-transform: uppercase; margin-bottom: 6px; }
.kpg-info-pop__list { margin: 0; padding-left: 18px; }
.kpg-info-pop__list li { font-size: 11.5px; color: var(--bf-text, #242424); line-height: 1.5; margin-bottom: 4px; }

/* License badge */
.bfusion-license-badge-wrap { position: absolute; bottom: 4px; left: 8px; z-index: 20; pointer-events: none; }
.bfusion-license-badge { display: inline-flex; align-items: center; gap: 5px; padding: 3px 10px; border-radius: 4px; font-size: 9px; line-height: 1.3; pointer-events: auto; max-width: 380px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.bfusion-license-badge--valid { background: rgba(5,150,105,0.08); border: 1px solid rgba(5,150,105,0.25); color: #059669; }
.bfusion-license-badge--invalid { background: rgba(220,38,38,0.06); border: 1px solid rgba(220,38,38,0.20); color: #dc2626; }
.bfusion-license-badge__icon { font-size: 11px; flex-shrink: 0; }

/* Empty state / landing */
.bfusion-landing-wrap { width: 100%; height: 100%; display: flex; flex-direction: column; justify-content: center; align-items: center; background: var(--bf-bg, #FFFFFF); }
.bfusion-empty { display: flex; width: 100%; height: 100%; align-items: center; justify-content: center; padding: 20px; }
.bfusion-empty__message { font-size: 12px; color: var(--bf-muted, #667079); font-weight: 400; text-align: center; }

/* ─────────────────────────────────────────────────────────────────────────
 * Column configure dialog — modal overlay launched from the ⚙ gear icon.
 * Without these rules the dialog HTML spills below the grid as plain text.
 * ───────────────────────────────────────────────────────────────────────── */
.kpg-dialog {
    position: absolute;
    inset: 0;
    z-index: 40;
    background: rgba(15, 23, 42, 0.32);
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 24px;
}
.kpg-dialog__panel {
    background: var(--bf-bg, #FFFFFF);
    border-radius: 8px;
    width: 100%;
    max-width: 600px;
    max-height: 88%;
    display: flex;
    flex-direction: column;
    box-shadow: 0 20px 50px rgba(15, 23, 42, 0.32);
    overflow: hidden;
    font-size: var(--kpg-dialog-fs, 13.5px);
}
.kpg-dialog__header {
    padding: 14px 22px;
    font-size: calc(var(--kpg-dialog-fs, 13.5px) + 1px);
    font-weight: 600;
    color: var(--bf-strong, #1F2A44);
    background: var(--bf-surface-alt, #F4F5F7);
    border-bottom: 1px solid var(--bf-rule, #E5E7EB);
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
}
.kpg-dialog__title {
    flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.kpg-dialog__moves { display: inline-flex; gap: 6px; flex-shrink: 0; }
.kpg-dialog__body {
    padding: 16px 20px 8px;
    overflow-y: auto;
    flex: 1;
    min-height: 0;
}
.kpg-dialog__footer {
    padding: 12px 20px;
    background: var(--bf-surface-alt, #F4F5F7);
    border-top: 1px solid var(--bf-rule, #E5E7EB);
    display: flex;
    align-items: center;
    gap: 10px;
}
.kpg-dialog__footer-spacer { flex: 1; }

/* Form fields inside the dialog */
.kpg-field { margin-bottom: 16px; }
.kpg-field--row { display: flex; gap: 14px; }
.kpg-field__half { flex: 1; min-width: 0; }
.kpg-field--checkbox label {
    display: inline-flex; align-items: center; gap: 7px;
    font-size: var(--kpg-dialog-fs, 13.5px); color: var(--bf-strong, #1F2A44); cursor: pointer;
}
.kpg-field--checkbox input { margin: 0; }
.kpg-field--section {
    margin-top: 6px;
    padding-top: 14px;
    border-top: 1px solid var(--bf-rule, #E5E7EB);
}
.kpg-field__sectionhead {
    font-size: calc(var(--kpg-dialog-fs, 13.5px) - 2px);
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    color: var(--bf-strong, #1F2A44);
    margin-bottom: 6px;
}
.kpg-field__label {
    display: block;
    font-size: calc(var(--kpg-dialog-fs, 13.5px) - 1px);
    font-weight: 600;
    color: var(--bf-text, #242424);
    margin-bottom: 6px;
}
.kpg-field__select,
.kpg-field__input {
    width: 100%;
    box-sizing: border-box;
    padding: 8px 11px;
    border: 1px solid var(--bf-rule, #E5E7EB);
    border-radius: 4px;
    font-size: var(--kpg-dialog-fs, 13.5px);
    color: var(--bf-strong, #1F2A44);
    background: var(--bf-bg, #FFFFFF);
    outline: 0;
    font-family: inherit;
}
.kpg-field__select:focus,
.kpg-field__input:focus {
    border-color: var(--kpg-header-band, #8b1a2e);
    box-shadow: 0 0 0 2px rgba(139, 26, 46, 0.10);
}
.kpg-field__hint {
    margin-top: 6px;
    font-size: calc(var(--kpg-dialog-fs, 13.5px) - 2px);
    color: var(--bf-muted, #667079);
    line-height: 1.45;
}
.kpg-field__hint code {
    background: var(--bf-surface-alt, #F4F5F7);
    padding: 1px 5px;
    border-radius: 3px;
    font-size: 10.5px;
    font-family: "Cascadia Mono", "Consolas", monospace;
}

/* Multi-measure checklist (sparkline / box-plot / RAG participants) */
.kpg-checklist {
    border: 1px solid var(--bf-rule, #E5E7EB);
    border-radius: 4px;
    max-height: 160px;
    overflow-y: auto;
    background: var(--bf-bg, #FFFFFF);
    padding: 4px 0;
}
.kpg-checklist__item {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 7px 11px;
    font-size: calc(var(--kpg-dialog-fs, 13.5px) - 1px);
    color: var(--bf-strong, #1F2A44);
    cursor: pointer;
    user-select: none;
}
.kpg-checklist__item:hover { background: var(--bf-surface-alt, #F4F5F7); }
.kpg-checklist__item input { margin: 0; flex-shrink: 0; }
.kpg-checklist__item--anchor {
    background: rgba(29, 78, 216, 0.06);
    border-bottom: 1px solid var(--bf-rule, #E5E7EB);
    cursor: default;
    font-weight: 600;
}
.kpg-checklist__tag {
    margin-left: auto;
    font-size: 10px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.4px;
    color: var(--kpg-accent, #1d4ed8);
    background: rgba(29, 78, 216, 0.10);
    padding: 2px 7px;
    border-radius: 999px;
    flex-shrink: 0;
}

/* Buttons (dialog Apply/Cancel + mini Move ← / →) */
.kpg-btn {
    padding: 9px 22px;
    border-radius: 999px;
    border: 1px solid transparent;
    font-size: var(--kpg-dialog-fs, 13.5px);
    font-weight: 600;
    cursor: pointer;
    transition: all 0.12s ease;
    min-width: 96px;
    font-family: inherit;
}
.kpg-btn--ghost {
    background: var(--bf-bg, #FFFFFF);
    color: var(--bf-strong, #1F2A44);
    border-color: var(--bf-rule, #E5E7EB);
}
.kpg-btn--ghost:hover { background: var(--bf-surface-alt, #F4F5F7); border-color: var(--bf-rule, #E5E7EB); }
.kpg-btn--primary {
    background: var(--bf-band, #1F2A44);
    color: #ffffff;
    border-color: #4361ee;
}
.kpg-btn--primary:hover { background: var(--bf-band, #1F2A44); border-color: #3651d9; }
.kpg-btn--mini {
    padding: 4px 10px;
    font-size: 11px;
    min-width: 0;
    background: var(--bf-bg, #FFFFFF);
    color: var(--bf-strong, #1F2A44);
    border: 1px solid var(--bf-rule, #E5E7EB);
    font-weight: 500;
    border-radius: 4px;
    cursor: pointer;
    font-family: inherit;
}
.kpg-btn--mini:disabled { opacity: 0.4; cursor: not-allowed; }
.kpg-btn--reset { color: var(--bf-muted, #667079); }
.kpg-btn--reset:hover { color: var(--bf-strong, #1F2A44); }

/* Toast — "Copied N rows to clipboard" */
.kpg-toast {
    position: absolute;
    bottom: 50px;
    left: 50%;
    transform: translateX(-50%);
    background: var(--bf-band, #1F2A44);
    color: #ffffff;
    padding: 8px 16px;
    border-radius: 999px;
    font-size: 12px;
    font-weight: 500;
    box-shadow: 0 6px 16px rgba(0,0,0,0.18);
    z-index: 50;
    pointer-events: none;
    transition: opacity 0.3s ease;
}
.kpg-toast--fade { opacity: 0; }

/* ─────────────────────────────────────────────────────────────────────────
 * v22 — Inline filters, row expand, saved views
 * ───────────────────────────────────────────────────────────────────────── */

/* Filter funnel button in each column header (next to the gear) */
.kpg-th__funnel {
    background: transparent;
    border: 0;
    color: var(--kpg-header-text, #ffffff);
    opacity: 0.55;
    padding: 2px 4px;
    cursor: pointer;
    display: inline-flex;
    align-items: center;
    border-radius: 3px;
}
.kpg-th__funnel:hover { opacity: 1; background: rgba(0,0,0,0.12); }
.kpg-th__funnel--active { opacity: 1; color: #fcd34d; }

/* Filter popover — modal-ish but lighter than the configure dialog */
.kpg-filterpop {
    position: absolute;
    inset: 0;
    z-index: 35;
    background: rgba(15,23,42,0.18);
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 24px;
}
.kpg-filterpop__panel {
    background: var(--bf-bg, #FFFFFF);
    border-radius: 8px;
    width: 100%;
    max-width: 340px;
    max-height: 80%;
    display: flex;
    flex-direction: column;
    box-shadow: 0 12px 32px rgba(15,23,42,0.22);
    overflow: hidden;
}
.kpg-filterpop__head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 10px 14px;
    background: var(--bf-surface-alt, #F4F5F7);
    border-bottom: 1px solid var(--bf-rule, #E5E7EB);
    font-size: 13px;
    font-weight: 600;
    color: var(--bf-strong, #1F2A44);
}
.kpg-filterpop__title { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.kpg-filterpop__close {
    background: transparent;
    border: 0;
    cursor: pointer;
    color: var(--bf-muted, #667079);
    font-size: 18px;
    line-height: 1;
    padding: 0 4px;
}
.kpg-filterpop__body {
    padding: 12px 14px;
    overflow-y: auto;
    flex: 1;
    min-height: 0;
}
.kpg-filterpop__count {
    font-size: 11px;
    color: var(--bf-muted, #667079);
    margin-bottom: 6px;
    text-transform: uppercase;
    letter-spacing: 0.4px;
    font-weight: 600;
}
.kpg-filterpop__foot {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 8px 14px;
    background: var(--bf-surface-alt, #F4F5F7);
    border-top: 1px solid var(--bf-rule, #E5E7EB);
}

/* Row expand chevron in the identity cell — tracks body font so it's readable
   at any typography setting. The button's hit area sits ~30% larger than the
   glyph so it stays comfortably clickable. */
.kpg-id__chev {
    background: transparent;
    border: 0;
    color: var(--bf-muted, #667079);
    cursor: pointer;
    padding: 0;
    width:  calc(var(--kpg-body-fs, 13px) * 1.3);
    height: calc(var(--kpg-body-fs, 13px) * 1.3);
    display: inline-flex;
    align-items: center;
    justify-content: center;
    font-size: var(--kpg-body-fs, 13px);
    font-weight: 600;
    line-height: 1;
    flex-shrink: 0;
    transition: color 0.12s ease;
}
.kpg-id__chev:hover { color: var(--bf-strong, #1F2A44); }
.kpg-id__chev--open { color: var(--kpg-accent, #1d4ed8); }

/* Detail panel rendered as a full-width <tr> below an expanded row — now carries
   CONTEXTUAL insights rather than a flat dump of the row's own cell values. */
.kpg-row--detail { cursor: default; }
.kpg-row--detail .kpg-td--detail {
    background: linear-gradient(180deg, var(--bf-bg, #FFFFFF) 0%, var(--bf-surface-alt, #F4F5F7) 100%);
    border-bottom: 2px solid var(--kpg-insight-accent, #E8612A);
    padding: 16px 22px 18px 40px;
}
.kpg-detail__title {
    font-size: calc(var(--kpg-body-fs, 13px) + 2px);
    font-weight: 700;
    color: var(--bf-strong, #1F2A44);
    margin-bottom: 4px;
    display: flex;
    align-items: center;
    gap: 10px;
    flex-wrap: wrap;
}
.kpg-detail__title-tag {
    font-size: calc(var(--kpg-body-fs, 13px) - 4px);
    font-weight: 700;
    color: var(--kpg-insight-accent, #E8612A);
    text-transform: uppercase;
    letter-spacing: 0.6px;
    background: rgba(232, 97, 42, 0.10);
    padding: 2px 8px;
    border-radius: 999px;
}
.kpg-detail__meta {
    font-size: calc(var(--kpg-body-fs, 13px) - 2px);
    color: var(--bf-muted, #667079);
    margin-bottom: 10px;
}
.kpg-detail__narrative {
    font-size: var(--kpg-body-fs, 13px);
    color: var(--bf-text, #242424);
    line-height: 1.5;
    margin-bottom: 12px;
    padding: 8px 12px;
    background: rgba(232, 97, 42, 0.06);
    border-left: 3px solid var(--kpg-insight-accent, #E8612A);
    border-radius: 4px;
}
.kpg-detail__subhead {
    font-size: calc(var(--kpg-body-fs, 13px) - 3px);
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    color: var(--bf-muted, #667079);
    margin: 14px 0 6px;
    padding-top: 8px;
    border-top: 1px dashed var(--bf-rule, #E5E7EB);
}
.kpg-detail__list {
    margin: 0;
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
    gap: 8px 24px;
}
.kpg-detail__list--tips { grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); }
.kpg-detail__row {
    display: flex;
    flex-direction: column;
    background: var(--bf-bg, #FFFFFF);
    border: 1px solid var(--bf-rule, #E5E7EB);
    border-radius: 6px;
    padding: 8px 12px;
}
.kpg-detail__list dt {
    font-size: calc(var(--kpg-body-fs, 13px) - 3px);
    font-weight: 700;
    color: var(--bf-muted, #667079);
    text-transform: uppercase;
    letter-spacing: 0.4px;
}
.kpg-detail__list dd {
    font-size: var(--kpg-body-fs, 13px);
    color: var(--bf-strong, #1F2A44);
    margin: 0;
    font-variant-numeric: tabular-nums;
    display: flex;
    flex-direction: column;
    gap: 4px;
}
.kpg-detail__val {
    font-weight: 700;
    font-size: calc(var(--kpg-body-fs, 13px) + 1px);
}
.kpg-detail__chips {
    display: inline-flex;
    flex-wrap: wrap;
    gap: 4px;
}
.kpg-detail__chip {
    font-size: calc(var(--kpg-body-fs, 13px) - 3px);
    font-weight: 600;
    background: var(--bf-surface, #F8F9FB);
    color: var(--bf-text, #242424);
    padding: 2px 8px;
    border-radius: 999px;
    border: 1px solid var(--bf-rule, #E5E7EB);
}
.kpg-detail__chip--pos { color: #047857; background: #d1fae5; border-color: #6ee7b7; }
.kpg-detail__chip--neg { color: #b91c1c; background: #fee2e2; border-color: #fca5a5; }
.kpg-detail__chip--flat { color: var(--bf-muted, #667079); }

/* Saved views popover */
.kpg-views-pop {
    position: absolute;
    inset: 0;
    z-index: 35;
    background: rgba(15,23,42,0.18);
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 24px;
}
.kpg-views-pop__panel {
    background: var(--bf-bg, #FFFFFF);
    border-radius: 8px;
    width: 100%;
    max-width: 380px;
    max-height: 80%;
    display: flex;
    flex-direction: column;
    box-shadow: 0 12px 32px rgba(15,23,42,0.22);
    overflow: hidden;
}
.kpg-views-pop__head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 10px 14px;
    background: var(--bf-surface-alt, #F4F5F7);
    border-bottom: 1px solid var(--bf-rule, #E5E7EB);
    font-size: 13px;
    font-weight: 600;
}
.kpg-views-pop__title { flex: 1; }
.kpg-views-pop__body {
    padding: 12px 14px;
    overflow-y: auto;
    flex: 1;
    min-height: 0;
}
.kpg-views-list { display: flex; flex-direction: column; gap: 4px; margin-bottom: 10px; }
.kpg-views-list__row {
    display: flex;
    align-items: center;
    gap: 4px;
    border-radius: 4px;
    border: 1px solid var(--bf-rule, #E5E7EB);
    background: var(--bf-bg, #FFFFFF);
}
.kpg-views-list__row:hover { border-color: var(--kpg-accent, #1d4ed8); background: var(--bf-bg, #FFFFFF); }
.kpg-views-list__load {
    flex: 1;
    text-align: left;
    background: transparent;
    border: 0;
    padding: 8px 12px;
    cursor: pointer;
    font-size: 12.5px;
    color: var(--bf-strong, #1F2A44);
    font-weight: 600;
    border-radius: 4px;
    font-family: inherit;
}
.kpg-views-list__del {
    background: transparent;
    border: 0;
    color: var(--bf-muted, #667079);
    cursor: pointer;
    padding: 6px 10px;
    font-size: 16px;
    line-height: 1;
    border-radius: 50%;
}
.kpg-views-list__del:hover { color: #dc2626; background: rgba(220,38,38,0.08); }
.kpg-views-pop__save {
    display: flex;
    gap: 6px;
    padding-top: 8px;
    border-top: 1px solid var(--bf-rule, #E5E7EB);
}
.kpg-views-pop__save .kpg-field__input { flex: 1; }
/* Timeline column — mini Gantt bar per row on a date scale shared by all rows. */
.kpg-th--timeline { vertical-align: top; }
.kpg-tl-axis { position: relative; height: 14px; margin-top: 4px; font-size: calc(var(--kpg-header-fs, 12.5px) - 3px); font-weight: 500; opacity: 0.85; overflow: hidden; }
.kpg-tl-axis__tick { position: absolute; top: 0; padding-left: 3px; border-left: 1px solid currentColor; line-height: 14px; white-space: nowrap; opacity: 0.75; }
.kpg-tl-axis__tick--major { opacity: 1; font-weight: 700; }
.kpg-tl-axis__today { position: absolute; top: 3px; transform: translateX(-50%); font-size: 8px; line-height: 1; color: var(--kpg-insight-accent, #E8612A); }
.kpg-tl { position: relative; height: 16px; min-width: 100px; }
.kpg-tl__bar { position: absolute; top: 3px; height: 10px; min-width: 3px; border-radius: 3px; background: var(--kpg-plan, #cbd5e1); overflow: hidden; }
.kpg-tl__done { display: block; height: 100%; background: var(--kpg-accent, #1d4ed8); }
.kpg-tl__bar--done .kpg-tl__done { background: var(--kpg-ok, #16a34a); }
.kpg-tl__bar--ontrack .kpg-tl__done { background: var(--kpg-ok, #16a34a); }
.kpg-tl__bar--behind .kpg-tl__done, .kpg-tl__bar--overdue .kpg-tl__done { background: var(--kpg-warn, #d97706); }
/* Striped, never solid: a solid block reads as progress. The solid fill is % done only. */
.kpg-tl__behind { position: absolute; top: 3px; height: 10px; background: repeating-linear-gradient(135deg, var(--kpg-risk, #dc2626) 0 1.5px, transparent 1.5px 4.5px); box-shadow: inset -1.5px 0 0 var(--kpg-risk, #dc2626); }
.kpg-tl__over { position: absolute; top: 7px; height: 2px; background: var(--kpg-risk, #dc2626); }
.kpg-tl__over::after { content: ""; position: absolute; right: -1px; top: -3px; width: 2px; height: 8px; background: var(--kpg-risk, #dc2626); }
.kpg-tl__today { position: absolute; top: -8px; bottom: -8px; width: 0; border-left: 1px dashed var(--kpg-insight-accent, #E8612A); opacity: 0.8; pointer-events: none; }
.kpg-tl__ms { position: absolute; top: 0; transform: translateX(-50%); font-size: 12px; line-height: 16px; color: var(--kpg-accent, #1d4ed8); }
.kpg-tl__ms--done { color: var(--kpg-ok, #16a34a); }
.kpg-tl__ms--overdue, .kpg-tl__ms--behind { color: var(--kpg-risk, #dc2626); }
.kpg-tl--summary .kpg-tl__bar { top: 5px; height: 6px; border-radius: 1px; background: var(--bf-muted, #667079); opacity: 0.9; overflow: visible; }
.kpg-tl--summary .kpg-tl__bar::before, .kpg-tl--summary .kpg-tl__bar::after { content: ""; position: absolute; top: 0; width: 2px; height: 10px; background: inherit; }
.kpg-tl--summary .kpg-tl__bar::before { left: 0; }
.kpg-tl--summary .kpg-tl__bar::after { right: 0; }
.kpg-tl--summary .kpg-tl__done { background: var(--bf-strong, #1F2A44); }
.kpg-tl--summary .kpg-tl__bar--alert::after { background: var(--kpg-risk, #dc2626); }
.kpg-legend__tl { display: inline-block; width: 14px; height: 8px; border-radius: 2px; }
.kpg-legend__tl--done { background: var(--kpg-ok, #16a34a); }
.kpg-legend__tl--behind { background: repeating-linear-gradient(135deg, var(--kpg-risk, #dc2626) 0 1.5px, transparent 1.5px 4.5px); background-color: var(--kpg-plan, #cbd5e1); }
.kpg-legend__tl--today { width: 0; height: 12px; border-radius: 0; border-left: 1px dashed var(--kpg-insight-accent, #E8612A); }
/* Focus mode — "Why" column and the nothing-to-show state. */
.kpg-why { display: flex; flex-wrap: wrap; gap: 4px; min-width: 150px; }
.kpg-why__chip { font-size: calc(var(--kpg-body-fs, 13px) - 2.5px); padding: 1px 7px; white-space: nowrap; }
.kpg-focus-empty { margin: 28px auto; max-width: 420px; text-align: center; color: var(--bf-muted, #667079); font-size: var(--kpg-body-fs, 13px); display: flex; flex-direction: column; gap: 8px; align-items: center; }
.kpg-focus-empty__title { font-size: calc(var(--kpg-body-fs, 13px) + 3px); font-weight: 600; color: var(--kpg-ok, #16a34a); }
/* Question chips ("Ask") under the legend bar. */
.kpg-ask { padding: 6px 14px 7px; border-bottom: 1px solid var(--bf-rule, #E5E7EB); background: var(--bf-bg, #FFFFFF); display: flex; flex-direction: column; gap: 6px; }
.kpg-ask__row { display: flex; flex-wrap: wrap; align-items: center; gap: 6px; }
.kpg-ask__label { font-size: calc(var(--kpg-button-fs, 11.5px) - 0.5px); font-weight: 700; letter-spacing: 0.06em; text-transform: uppercase; color: var(--kpg-insight-accent, #E8612A); margin-right: 2px; }
.kpg-ask__chip { display: inline-flex; align-items: center; gap: 6px; padding: 3px 5px 3px 11px; border-radius: 999px; border: 1px solid var(--bf-rule, #E5E7EB); background: var(--bf-surface-alt, #F4F5F7); color: var(--bf-text, #242424); font: inherit; font-size: var(--kpg-button-fs, 11.5px); cursor: pointer; transition: border-color 0.12s ease, background 0.12s ease; }
.kpg-ask__chip:hover { border-color: var(--kpg-insight-accent, #E8612A); }
.kpg-ask__chip--active { background: rgba(232, 97, 42, 0.12); border-color: var(--kpg-insight-accent, #E8612A); color: var(--bf-strong, #1F2A44); font-weight: 600; }
.kpg-ask__count { min-width: 18px; padding: 0 5px; border-radius: 999px; background: var(--bf-bg, #FFFFFF); border: 1px solid var(--bf-rule, #E5E7EB); font-size: calc(var(--kpg-button-fs, 11.5px) - 1px); font-weight: 700; line-height: 16px; text-align: center; font-variant-numeric: tabular-nums; }
.kpg-ask__count--none { color: var(--kpg-ok, #16a34a); }
.kpg-ask__chip--active .kpg-ask__count { background: var(--kpg-insight-accent, #E8612A); border-color: var(--kpg-insight-accent, #E8612A); color: #ffffff; }
.kpg-ask__answer { display: flex; align-items: baseline; gap: 8px; font-size: var(--kpg-body-fs, 13px); color: var(--bf-strong, #1F2A44); }
.kpg-ask__arrow { color: var(--kpg-insight-accent, #E8612A); font-weight: 700; }
.kpg-ask__text { flex: 1; font-weight: 600; white-space: normal; }
.kpg-ask__clear { border: 0; background: transparent; color: var(--bf-muted, #667079); cursor: pointer; font-size: var(--kpg-body-fs, 13px); padding: 0 4px; }
.kpg-ask__clear:hover { color: var(--bf-strong, #1F2A44); }
.kpg-td--hl { box-shadow: inset 0 0 0 999px rgba(232, 97, 42, 0.08); }
.kpg-th--hl { box-shadow: inset 0 -3px 0 var(--kpg-insight-accent, #E8612A); }
/* Bottom bar: sheet tabs on the right — the licence badge owns the bottom-left corner. */
.kpg-bottom { flex: 0 0 auto; display: flex; justify-content: flex-end; align-items: stretch; gap: 12px; min-height: 26px; padding: 0 8px 0 var(--kpg-badge-w, 280px); border-top: 1px solid var(--bf-rule, #E5E7EB); background: var(--bf-surface-alt, #F4F5F7); overflow: hidden; }
.kpg-tabs { display: flex; align-items: stretch; gap: 1px; overflow-x: auto; scrollbar-width: none; }
.kpg-tab { border: 0; border-top: 2px solid transparent; background: transparent; color: var(--bf-muted, #667079); font: inherit; font-size: var(--kpg-button-fs, 11.5px); padding: 3px 12px 4px; cursor: pointer; white-space: nowrap; }
.kpg-tab:hover { color: var(--bf-strong, #1F2A44); background: var(--bf-bg, #FFFFFF); }
.kpg-tab--active { background: var(--bf-bg, #FFFFFF); color: var(--bf-strong, #1F2A44); font-weight: 600; border-top-color: var(--kpg-insight-accent, #E8612A); }
.kpg-tab--saved { font-style: italic; }
.kpg-tab--add { font-weight: 700; padding: 3px 9px 4px; }
/* Right-click header menu. */
.kpg-menu-overlay { position: absolute; inset: 0; z-index: 60; }
.kpg-menu { position: absolute; min-width: 210px; max-width: 280px; background: var(--bf-bg, #FFFFFF); color: var(--bf-text, #242424); border: 1px solid var(--bf-rule, #E5E7EB); border-radius: 6px; box-shadow: 0 8px 24px rgba(15, 23, 42, 0.18); padding: 4px; font-size: var(--kpg-body-fs, 13px); }
.kpg-menu__title { padding: 5px 10px 4px; font-size: calc(var(--kpg-body-fs, 13px) - 2px); font-weight: 700; letter-spacing: 0.04em; text-transform: uppercase; color: var(--bf-muted, #667079); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.kpg-menu__item { display: flex; align-items: center; gap: 8px; width: 100%; border: 0; background: transparent; color: inherit; font: inherit; text-align: left; padding: 6px 10px; border-radius: 4px; cursor: pointer; }
.kpg-menu__item:hover, .kpg-menu__item:focus { background: var(--bf-surface-alt, #F4F5F7); outline: none; }
.kpg-menu__glyph { width: 14px; text-align: center; color: var(--bf-muted, #667079); }
.kpg-menu__sep { height: 1px; margin: 4px 6px; background: var(--bf-rule, #E5E7EB); }
/* Cell selection + status bar. */
.kpg-td--sel { box-shadow: inset 0 0 0 999px rgba(29, 78, 216, 0.10), inset 0 0 0 1px rgba(29, 78, 216, 0.35); }
.kpg-selecting, .kpg-selecting * { user-select: none; cursor: cell; }
.kpg-status { flex: 1 1 auto; min-width: 0; display: flex; align-items: center; gap: 16px; font-size: var(--kpg-button-fs, 11.5px); color: var(--bf-strong, #1F2A44); white-space: nowrap; overflow: hidden; font-variant-numeric: tabular-nums; }
.kpg-status--idle { color: var(--bf-muted, #667079); opacity: 0.75; font-style: italic; }
.kpg-status__part { font-weight: 600; }
.kpg-status__label { font-weight: 400; color: var(--bf-muted, #667079); margin-right: 5px; }
.kpg-calc-error { color: #dc2626; font-size: calc(var(--kpg-dialog-fs, 13.5px) - 1px); margin-top: 6px; min-height: 1em; }
/* ── Compact grid (KPI Grid v2 part B) ─────────────────────────────── */
.kpg-grid.kpg-grid--compact .kpg-td { padding: 5px 12px; }
.kpg-grid.kpg-grid--compact .kpg-th { padding: 7px 12px; }
.kpg-grid.kpg-grid--compact .kpg-id { gap: 6px; white-space: nowrap; min-width: 0; }
.kpg-grid.kpg-grid--compact .kpg-id__text { flex-direction: row; align-items: baseline; gap: 6px; min-width: 0; overflow: hidden; }
.kpg-grid.kpg-grid--compact .kpg-id__name { overflow: hidden; text-overflow: ellipsis; flex-shrink: 1; }
.kpg-grid.kpg-grid--compact .kpg-id__meta { margin-top: 0; overflow: hidden; text-overflow: ellipsis; flex-shrink: 2; }
.kpg-grid.kpg-grid tbody .kpg-row.kpg-row--group .kpg-td { background: var(--kpg-subtotal-bg-0, #e0f2fe); font-weight: 600; border-top: 1px solid rgba(0,0,0,0.08); }
.kpg-grid.kpg-grid tbody .kpg-row.kpg-row--group-depth-1 .kpg-td { background: var(--kpg-subtotal-bg-1, #fae8ff); }
.kpg-grid.kpg-grid tbody .kpg-row.kpg-row--group-depth-2 .kpg-td { background: var(--kpg-subtotal-bg-2, #d1fae5); }
.kpg-grid .kpg-row--group:hover .kpg-td { filter: brightness(0.97); }
.kpg-grid.kpg-grid--compact .kpg-row--group .kpg-td { padding-top: 6px; padding-bottom: 6px; }
.kpg-grid .kpg-td--group-depth-1 { padding-left: 28px; }
.kpg-grid .kpg-td--group-depth-2 { padding-left: 42px; }
.kpg-group__key--blank { font-style: italic; font-weight: 500; opacity: 0.7; }
.kpg-group__count { display: inline-block; margin-left: 8px; padding: 0 6px; border-radius: 8px; font-size: 10.5px; font-weight: 600; line-height: 16px; background: rgba(0,0,0,0.06); color: inherit; opacity: 0.8; }
/* ── Decision insights + details in the rail (KPI Grid v2 part D) ──── */
.kpg-insight--decision { cursor: pointer; transition: box-shadow 0.12s ease, background 0.12s ease; }
.kpg-insight--decision:hover { box-shadow: 0 0 0 1px var(--kpg-insight-accent, #E8612A); }
.kpg-insight--decision:focus-visible { outline: 2px solid var(--kpg-accent, #1d4ed8); outline-offset: 1px; }
.kpg-insight--active { box-shadow: 0 0 0 2px var(--kpg-insight-accent, #E8612A); }
.kpg-insight__title { font-size: calc(var(--kpg-body-fs, 13px) - 1px); font-weight: 700; line-height: 1.3; }
.kpg-insight__action { font-size: calc(var(--kpg-body-fs, 13px) - 2px); font-weight: 600; line-height: 1.4; margin-top: 4px; }
.kpg-insight__rows { font-size: calc(var(--kpg-body-fs, 13px) - 3px); opacity: 0.65; margin-top: 4px; }
.kpg-rail__filter { display: flex; align-items: center; justify-content: space-between; gap: 8px; width: 100%; margin: 0 0 8px; padding: 6px 10px; border: 1px solid var(--kpg-insight-accent, #E8612A); border-radius: 6px; background: transparent; color: inherit; font: inherit; font-size: calc(var(--kpg-body-fs, 13px) - 2px); font-weight: 600; text-align: left; cursor: pointer; }
.kpg-rail__filter-x { flex-shrink: 0; opacity: 0.7; }
.kpg-rail .kpg-detail { padding: 8px 10px; border-radius: 6px; border: 1px solid rgba(127,127,127,0.25); }
.kpg-rail .kpg-detail__title { display: flex; justify-content: space-between; align-items: flex-start; gap: 6px; font-size: calc(var(--kpg-body-fs, 13px) - 0px); }
.kpg-detail__close { background: transparent; border: 0; color: inherit; opacity: 0.6; cursor: pointer; padding: 0 2px; font-size: 12px; }
.kpg-detail__close:hover { opacity: 1; }
.kpg-rail .kpg-detail__list, .kpg-rail .kpg-detail__list--tips { display: flex; flex-direction: column; gap: 6px; }
.kpg-rail .kpg-detail__row { padding: 4px 0; border: 0; border-bottom: 1px solid rgba(127,127,127,0.15); border-radius: 0; background: transparent; }
.kpg-rail .kpg-detail__chips { flex-wrap: wrap; }
/* ── KPI tile visuals + detail chart (KPI Grid v2 part C) ───────────── */
.kpg-tile__chart { margin-top: 6px; }
.kpg-tile__chart--donut { display: flex; align-items: center; gap: 10px; }
.kpg-tile__chart--gauge { display: flex; flex-direction: column; align-items: flex-start; }
.kpg-tile__legend { list-style: none; margin: 0; padding: 0; min-width: 0; flex: 1; font-size: 11px; line-height: 1.45; }
.kpg-tile__legend li { display: flex; align-items: center; gap: 5px; min-width: 0; }
.kpg-tile__swatch { width: 8px; height: 8px; border-radius: 2px; flex-shrink: 0; }
.kpg-tile__lname { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.kpg-tile__lval { font-variant-numeric: tabular-nums; opacity: 0.75; }
.kpg-tile__note { display: block; font-size: 11px; opacity: 0.75; margin-top: 3px; }
.kpg-tile__note--risk { color: var(--kpg-risk, #dc2626); opacity: 1; font-weight: 600; }
.kpg-bullet { position: relative; height: 10px; border-radius: 3px; background: rgba(127,127,127,0.18); }
.kpg-bullet__bar { position: absolute; left: 0; top: 2px; bottom: 2px; border-radius: 2px; }
.kpg-bullet__target { position: absolute; top: -3px; bottom: -3px; width: 2px; margin-left: -1px; background: currentColor; }
.kpg-stack { display: flex; height: 10px; border-radius: 3px; overflow: hidden; background: rgba(127,127,127,0.18); }
.kpg-stack span { display: block; height: 100%; }
.kpg-hbar { display: grid; grid-template-columns: minmax(0, 38%) 1fr auto; align-items: center; gap: 6px; font-size: 11px; line-height: 1.6; }
.kpg-hbar__label { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.kpg-hbar__track { position: relative; height: 7px; border-radius: 3px; background: rgba(127,127,127,0.16); }
.kpg-hbar__track span { position: absolute; left: 0; top: 0; bottom: 0; border-radius: 3px; }
.kpg-hbar__avg { position: absolute; top: -3px; bottom: -3px; width: 2px; margin-left: -1px; background: currentColor; opacity: 0.6; }
.kpg-hbar__val { font-variant-numeric: tabular-nums; text-align: right; }
.kpg-detail__bars { display: flex; flex-direction: column; gap: 4px; margin-top: 6px; }
.kpg-hbar--detail { grid-template-columns: minmax(0, 34%) 1fr auto; }
.kpg-detail__tools { display: inline-flex; align-items: center; gap: 4px; flex-shrink: 0; }
.kpg-detail__mode { background: transparent; border: 1px solid rgba(127,127,127,0.35); border-radius: 4px; color: inherit; font: inherit; font-size: 10.5px; padding: 1px 6px; cursor: pointer; }
.kpg-detail__mode:hover { border-color: var(--kpg-insight-accent, #E8612A); }
/* ── Suite chrome: insight panel + INSIGHTS rail (bfusion-FTEDecisionBoard) ── */
.kpg-panel { flex: 0 0 280px; width: 280px; max-width: 280px; box-sizing: border-box; padding: 8px; border-left: 1px solid var(--bf-rule, #E5E7EB); background: var(--bf-tile, #ffffff); min-height: 0; overflow-y: auto; overflow-x: hidden; font-size: var(--kpg-insight-fs, 12px); color: var(--bf-text, #242424); }
.bfusion-insight-strip { background: var(--bf-surface-alt, #F4F5F7); border-left: 1px solid var(--bf-rule, #E5E7EB); color: var(--bf-muted, #667079); cursor: pointer; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 10px; user-select: none; transition: background .15s ease, color .15s ease; flex: 0 0 26px; width: 26px; }
.bfusion-insight-strip__arrow { font-size: 10px; color: #D97B29; line-height: 1; }
.bfusion-insight-strip__label { writing-mode: vertical-rl; transform: rotate(180deg); letter-spacing: 0.18em; font-size: 9px; font-weight: 650; color: var(--bf-muted, #667079); text-transform: uppercase; }
.bfusion-insight-strip:hover, .bfusion-insight-strip:focus { background: var(--bf-rule, #E5E7EB); color: var(--bf-text, #242424); outline: none; }
.bfusion-insight-strip:focus-visible { outline: 2px solid #D97B29; outline-offset: -2px; }
.bfusion-scope-chip { appearance: none; display: inline-flex; align-items: center; gap: 6px; max-width: 100%; padding: 2px 8px; margin: 0 0 8px; border: 1px solid rgba(217, 123, 41, 0.35); border-radius: 999px; background: rgba(217, 123, 41, 0.08); color: #9a5418; font-family: inherit; font-size: 10px; font-weight: 600; cursor: pointer; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.bfusion-scope-chip__text { overflow: hidden; text-overflow: ellipsis; }
.bfusion-scope-chip__x { color: #b1712f; font-weight: 700; }
.bfusion-scope-chip:hover { background: rgba(217, 123, 41, 0.16); }
.bfusion-tooltip { position: absolute; z-index: 999; max-width: 260px; padding: 8px 12px; pointer-events: none; background: color-mix(in srgb, var(--bf-tile, #fff) 97%, transparent); border: 1px solid var(--bf-rule, #E5E7EB); border-radius: 6px; box-shadow: 0 3px 12px rgba(0, 0, 0, 0.12); font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif; font-size: 11px; line-height: 1.5; color: var(--bf-text, #242424); }
.bfusion-tooltip__head { font-weight: 600; border-bottom: 1px solid var(--bf-rule, #E5E7EB); padding-bottom: 3px; margin-bottom: 4px; }
.bfusion-tooltip__row { display: flex; justify-content: space-between; gap: 12px; }
.bfusion-tooltip__label { color: var(--bf-muted, #667079); display: inline-flex; align-items: center; gap: 5px; white-space: nowrap; }
.bfusion-tooltip__value { font-variant-numeric: tabular-nums; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.bfusion-tooltip__dot { width: 7px; height: 7px; border-radius: 50%; display: inline-block; flex: 0 0 auto; }
.kpg-panel [data-tone="good"] { --tone: #16a34a; }
.kpg-panel [data-tone="warn"] { --tone: #d97706; }
.kpg-panel [data-tone="bad"]  { --tone: #dc2626; }
.kpg-panel [data-tone="info"] { --tone: #1e40af; }
.kpg-verdict { display: flex; align-items: center; gap: 10px; padding: 8px 10px; margin-bottom: 8px; border-radius: 6px; background-color: color-mix(in srgb, var(--tone) 8%, var(--bf-tile, #fff)); border: 1px solid color-mix(in srgb, var(--tone) 30%, var(--bf-tile, #fff)); border-left: 4px solid var(--tone); }
.kpg-verdict__badge { flex: 0 0 auto; width: 38px; height: 38px; border-radius: 50%; background-color: var(--tone); color: #ffffff; display: flex; align-items: center; justify-content: center; font-size: 15px; font-weight: 700; }
.kpg-verdict__text { min-width: 0; }
.kpg-verdict__title { font-size: 12px; font-weight: 700; line-height: 1.3; color: color-mix(in srgb, var(--tone) 70%, var(--bf-text, #242424)); }
.kpg-verdict__sub { font-size: 10px; color: var(--bf-muted, #667079); margin-top: 2px; line-height: 1.35; }
.kpg-card { border-radius: 6px; padding: 8px; margin-bottom: 8px; background-color: color-mix(in srgb, var(--tone) 6%, var(--bf-tile, #fff)); border: 1px solid color-mix(in srgb, var(--tone) 28%, var(--bf-tile, #fff)); }
.kpg-card[data-tone="info"] { background-color: var(--bf-tile, #fff); border-color: var(--bf-rule, #E5E7EB); }
.kpg-card--active { box-shadow: 0 0 0 2px #D97B29; }
.kpg-card__head { display: flex; align-items: center; gap: 6px; margin-bottom: 6px; }
.kpg-card__icon { font-size: 12px; line-height: 1; color: var(--tone); }
.kpg-card__title { font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.4px; color: color-mix(in srgb, var(--tone) 70%, var(--bf-text, #242424)); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.kpg-card__headline { font-size: 11.5px; font-weight: 700; line-height: 1.35; margin-bottom: 3px; }
.kpg-card__item { font-size: 10.5px; line-height: 1.45; padding: 2px 0; color: var(--bf-text, #334155); }
.kpg-card__item--muted { color: var(--bf-muted, #64748b); font-style: italic; }
.kpg-card__action { font-weight: 600; }
.kpg-card__filter { appearance: none; margin-top: 6px; padding: 2px 8px; border-radius: 999px; border: 1px solid color-mix(in srgb, var(--tone) 40%, var(--bf-tile, #fff)); background: var(--bf-tile, #fff); color: color-mix(in srgb, var(--tone) 75%, var(--bf-text, #242424)); font-family: inherit; font-size: 10px; font-weight: 600; cursor: pointer; }
.kpg-card__filter:hover, .kpg-card__filter[aria-pressed="true"] { background: color-mix(in srgb, var(--tone) 12%, var(--bf-tile, #fff)); }
.kpg-card__filter:focus-visible { outline: 2px solid #D97B29; outline-offset: 1px; }
.kpg-panel .kpg-detail { padding: 0; background: transparent; border: 0; }
.kpg-panel .kpg-detail__title { display: flex; justify-content: space-between; align-items: flex-start; gap: 6px; font-size: 12px; }
.kpg-panel .kpg-detail__list, .kpg-panel .kpg-detail__list--tips { display: flex; flex-direction: column; gap: 6px; }
.kpg-panel .kpg-detail__row { padding: 4px 0; border: 0; border-bottom: 1px solid var(--bf-rule, #E5E7EB); border-radius: 0; background: transparent; }
.kpg-panel .kpg-detail__chips { flex-wrap: wrap; }
/* Hierarchy indent — one step per level for group headers and the rows under them.
   Higher specificity than the compact-row padding, which flattened every level. */
.kpg-grid.kpg-grid tbody .kpg-td--group-depth-0 { padding-left: 10px; }
.kpg-grid.kpg-grid tbody .kpg-td--group-depth-1 { padding-left: 28px; }
.kpg-grid.kpg-grid tbody .kpg-td--group-depth-2 { padding-left: 46px; }
.kpg-grid.kpg-grid tbody .kpg-td--group-depth-3 { padding-left: 64px; }
.kpg-grid.kpg-grid tbody .kpg-td--group-depth-4 { padding-left: 82px; }
.kpg-root.kpg-indent-on .kpg-grid.kpg-grid tbody .kpg-td--depth-1 { padding-left: 30px; }
.kpg-root.kpg-indent-on .kpg-grid.kpg-grid tbody .kpg-td--depth-2 { padding-left: 48px; }
.kpg-root.kpg-indent-on .kpg-grid.kpg-grid tbody .kpg-td--depth-3 { padding-left: 66px; }
.kpg-root.kpg-indent-on .kpg-grid.kpg-grid tbody .kpg-td--depth-4 { padding-left: 84px; }
.kpg-root.kpg-indent-on .kpg-grid.kpg-grid tbody .kpg-td--depth-5 { padding-left: 102px; }
.kpg-grid.kpg-grid tbody .kpg-row--group-depth-1 .kpg-td { background: var(--kpg-subtotal-bg-1, #fae8ff); }
.kpg-grid.kpg-grid tbody .kpg-row--group-depth-3 .kpg-td { background: var(--kpg-subtotal-bg-1, #fae8ff); }
.kpg-grid.kpg-grid tbody .kpg-row--group-depth-4 .kpg-td { background: var(--kpg-subtotal-bg-2, #d1fae5); }
